// Ground-truth AES ECB single-block encrypt, from scratch. Harness only (/tmp).
const SBOX = new Uint8Array(256);
const RCON = [0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36, 0x6c, 0xd8, 0xab, 0x4d];
(function build() {
  const p = new Uint8Array(256), l = new Uint8Array(256);
  let x = 1;
  for (let i = 0; i < 255; i++) { p[i] = x; l[x] = i; x = (x ^ ((x << 1) ^ ((x & 0x80) ? 0x11b : 0))) & 0xff; }
  const inv = (a) => (a === 0 ? 0 : p[255 - l[a]]);
  for (let i = 0; i < 256; i++) {
    const b = inv(i);
    let s = b;
    for (let k = 0; k < 4; k++) s ^= ((b << (k + 1)) | (b >>> (7 - k))) & 0xff;
    SBOX[i] = (s ^ 0x63) & 0xff;
  }
})();
const xt = (a) => ((a << 1) ^ ((a & 0x80) ? 0x1b : 0)) & 0xff;

function expandKey(key) {
  const nk = key.length / 4, nr = nk + 6;
  const w = [];
  for (let i = 0; i < nk; i++) w.push([key[4 * i], key[4 * i + 1], key[4 * i + 2], key[4 * i + 3]]);
  for (let i = nk; i < 4 * (nr + 1); i++) {
    let t = w[i - 1].slice();
    if (i % nk === 0) {
      t.push(t.shift());
      t = t.map((v) => SBOX[v]);
      t[0] ^= RCON[i / nk - 1];
    } else if (nk > 6 && i % nk === 4) {
      t = t.map((v) => SBOX[v]);
    }
    w.push(w[i - nk].map((v, j) => v ^ t[j]));
  }
  return { w, nr };
}

export function encryptBlock(key, block) {
  const { w, nr } = expandKey(key);
  let s = Array.from(block);
  const addRK = (r) => { for (let c = 0; c < 4; c++) for (let j = 0; j < 4; j++) s[4 * c + j] ^= w[4 * r + c][j]; };
  addRK(0);
  for (let round = 1; round <= nr; round++) {
    s = s.map((v) => SBOX[v]);
    // ShiftRows (column-major layout: byte index 4*c + r)
    const t = s.slice();
    for (let r = 1; r < 4; r++) for (let c = 0; c < 4; c++) s[4 * c + r] = t[4 * ((c + r) % 4) + r];
    if (round !== nr) {
      for (let c = 0; c < 4; c++) {
        const a0 = s[4 * c], a1 = s[4 * c + 1], a2 = s[4 * c + 2], a3 = s[4 * c + 3];
        s[4 * c] = xt(a0) ^ (xt(a1) ^ a1) ^ a2 ^ a3;
        s[4 * c + 1] = a0 ^ xt(a1) ^ (xt(a2) ^ a2) ^ a3;
        s[4 * c + 2] = a0 ^ a1 ^ xt(a2) ^ (xt(a3) ^ a3);
        s[4 * c + 3] = (xt(a0) ^ a0) ^ a1 ^ a2 ^ xt(a3);
      }
    }
    addRK(round);
  }
  return Uint8Array.from(s.map((v) => v & 0xff));
}

