import { spawnSync } from 'node:child_process';
import { encryptBlock } from './aes.mjs';
import { writeFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test16_executable';
const ALNUM = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
const RUNS = Number(process.argv[2] || 200);
const BLOCKS = Number(process.argv[3] || 32);
let seed = Number(process.argv[4] || 12345);
function rnd() { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x80000000; }
const randStr = (n) => Array.from({ length: n }, () => ALNUM[Math.floor(rnd() * ALNUM.length)]).join('');

// token map: byteValue -> Set of emitted token strings, per quote style
const map = new Map();          // byte -> Set(token)
const quoteObs = [];            // {has27, has22, quote}
const conflicts = [];
const bothQuoteSamples = [];
const singleQuoteInPayload = [];
let lines = 0, parsedOk = 0;
const rawSamples = [];

function tokenize(payload) {
  const toks = [];
  for (let i = 0; i < payload.length;) {
    if (payload[i] === '\\') {
      if (payload[i + 1] === 'x') { toks.push(payload.slice(i, i + 4)); i += 4; }
      else { toks.push(payload.slice(i, i + 2)); i += 2; }
    } else { toks.push(payload[i]); i += 1; }
  }
  return toks;
}

for (let run = 0; run < RUNS; run++) {
  const key = randStr(16);
  const data = randStr(16 * BLOCKS);
  const r = spawnSync(EXE, ['--key', key, '--data', data], { encoding: 'latin1' });
  if (r.status !== 0) { console.error('nonzero exit', r.status, r.stderr); continue; }
  const out = r.stdout;
  if (run === 0) rawSamples.push({ key, data, out });
  // exactly one \n per block, nothing else
  const parts = out.split('\n');
  if (parts[parts.length - 1] !== '') throw new Error('no trailing newline on last line');
  if (parts.length - 1 !== BLOCKS) throw new Error(`expected ${BLOCKS} lines got ${parts.length - 1}`);
  const kb = Buffer.from(key, 'utf8'), db = Buffer.from(data, 'utf8');
  for (let b = 0; b < BLOCKS; b++) {
    const truth = encryptBlock(kb, db.subarray(b * 16, b * 16 + 16));
    const line = parts[b];
    lines++;
    const q = line[1];
    if (line[0] !== 'b' || (q !== "'" && q !== '"')) throw new Error('bad prefix: ' + JSON.stringify(line));
    if (line[line.length - 1] !== q) throw new Error('bad suffix: ' + JSON.stringify(line));
    const payload = line.slice(2, -1);
    const toks = tokenize(payload);
    if (toks.length !== 16) { conflicts.push(['tokcount', line, Buffer.from(truth).toString('hex')]); continue; }
    parsedOk++;
    for (let i = 0; i < 16; i++) {
      const v = truth[i];
      if (!map.has(v)) map.set(v, new Map());
      const m = map.get(v);
      const kk = q + '|' + toks[i];
      m.set(kk, (m.get(kk) || 0) + 1);
    }
    const has27 = truth.includes(0x27), has22 = truth.includes(0x22);
    quoteObs.push({ has27, has22, q });
    if (has27 && has22 && bothQuoteSamples.length < 8) bothQuoteSamples.push({ key, blockIndex: b, dataBlock: db.subarray(b * 16, b * 16 + 16).toString('latin1'), hex: Buffer.from(truth).toString('hex'), line });
    if (has27 && !has22 && singleQuoteInPayload.length < 8) singleQuoteInPayload.push({ key, blockIndex: b, dataBlock: db.subarray(b * 16, b * 16 + 16).toString('latin1'), hex: Buffer.from(truth).toString('hex'), line });
  }
}

console.log(`lines=${lines} parsedOk=${parsedOk} conflicts=${conflicts.length}`);
console.log('distinct byte values seen:', map.size, '/256');
const missing = [];
for (let v = 0; v < 256; v++) if (!map.has(v)) missing.push(v);
console.log('missing:', missing.map((v) => '0x' + v.toString(16)).join(' ') || '(none)');

// report per-byte token, flag byte values whose token differs across quote styles
const rows = [];
for (let v = 0; v < 256; v++) {
  if (!map.has(v)) continue;
  const m = map.get(v);
  const byQ = { "'": new Set(), '"': new Set() };
  for (const k of m.keys()) { const [qq, ...rest] = k.split('|'); byQ[qq].add(rest.join('|')); }
  rows.push({ v, single: [...byQ["'"]], dbl: [...byQ['"']], counts: [...m.entries()] });
}
writeFileSync('/tmp/reprh/rows.json', JSON.stringify({ rows, quoteObs: quoteObs.slice(0, 0), bothQuoteSamples, singleQuoteInPayload }, null, 1));

// quote rule check
let bad = 0;
for (const o of quoteObs) {
  const expect = (o.has27 && !o.has22) ? '"' : "'";
  if (expect !== o.q) { bad++; if (bad < 5) console.log('QUOTE RULE VIOLATION', o); }
}
console.log('quote-rule violations:', bad, 'of', quoteObs.length);
console.log('blocks with 0x27 and 0x22:', quoteObs.filter((o) => o.has27 && o.has22).length);
console.log('blocks with 0x27 only   :', quoteObs.filter((o) => o.has27 && !o.has22).length);
console.log('blocks with 0x22 only   :', quoteObs.filter((o) => !o.has27 && o.has22).length);
console.log('--- both-quote samples ---');
for (const s of bothQuoteSamples) console.log(s.hex, JSON.stringify(s.line));
console.log('--- 0x27-only samples ---');
for (const s of singleQuoteInPayload) console.log(s.hex, JSON.stringify(s.line));

// byte -> token table
let tbl = '';
for (const r of rows) {
  const s = r.single.length ? r.single.join(',') : '-';
  const d = r.dbl.length ? r.dbl.join(',') : '-';
  const flag = (r.single.length > 1 || r.dbl.length > 1) ? '  <<AMBIG' : (r.single.length && r.dbl.length && r.single[0] !== r.dbl[0] ? '  <<QDIFF' : '');
  tbl += `0x${r.v.toString(16).padStart(2, '0')} single=${JSON.stringify(s)} double=${JSON.stringify(d)}${flag}\n`;
}
writeFileSync('/tmp/reprh/table.txt', tbl);
console.log('wrote /tmp/reprh/table.txt');

// Candidate reimplementation of Python's bytes repr, to be validated against the executable.
export function pyBytesRepr(buf) {
  const has27 = buf.includes(0x27), has22 = buf.includes(0x22);
  const q = (has27 && !has22) ? '"' : "'";
  let s = 'b' + q;
  for (const b of buf) {
    if (b === 0x5c) s += '\\\\';
    else if (b === 0x27) s += (q === "'" ? "\\'" : "'");
    else if (b === 0x22) s += '"';
    else if (b === 0x09) s += '\\t';
    else if (b === 0x0a) s += '\\n';
    else if (b === 0x0d) s += '\\r';
    else if (b >= 0x20 && b < 0x7f) s += String.fromCharCode(b);
    else s += '\\x' + b.toString(16).padStart(2, '0');
  }
  return s + q;
}

