      const a = expect.split('\n'), c = r.stdout.split('\n');
      for (let i = 0; i < a.length; i++) if (a[i] !== c[i]) console.log(' mine:', JSON.stringify(a[i]), '\n  exe:', JSON.stringify(c[i]));
    }
  }
}
console.log(`byte-exact stdout match: ${ok}/${RUNS} runs (${lines} lines), mismatches=${bad}`);

